// The wait prints this record; merge accepts only completed current-head evidence.
export const externalReviewSentence =
  "No external reviewer runs on app-authored PRs.";

export const reviewOutcomeTemplate = (head) => [
  "> _This was generated by AI._",
  "",
  `Head: ${head}`,
  "Standards: <actual Standards review outcome>",
  "Spec: <actual Spec review outcome>",
  externalReviewSentence,
];

export function completeReviewOutcome(body, head) {
  if (typeof body !== "string") return false;
  // The record is plain comment text, never a quoted example or HTML comment.
  if (/^\s*(?:`{3,}|~{3,})/m.test(body) || body.includes("<!--")) return false;
  const entries = body.split(/\r?\n/).flatMap((line) => {
    const match = /^(Head|Standards|Spec):[\t ]*(.*?)[\t ]*$/.exec(line);
    return match ? [[match[1], match[2]]] : [];
  });
  if (entries.length !== 3 || new Set(entries.map(([key]) => key)).size !== 3)
    return false;
  const fields = Object.fromEntries(entries);
  const completed = (value) =>
    Boolean(value?.trim()) &&
    !/^(?:TODO|TBD|placeholder|_?No response_?|<[^>]*>|\[[^\]]*\]|\{[^}]*\})[.!]?$/i.test(
      value,
    ) &&
    !/<actual (?:Standards|Spec) review outcome>/i.test(value);
  return (
    fields.Head === head &&
    completed(fields.Standards) &&
    completed(fields.Spec) &&
    body.split(/\r?\n/).some((line) => line === externalReviewSentence)
  );
}
